responses.body:
{{#if (gt (bodyRaw 'days') 0)}}
  {{#with (find (dataRaw 'cars') (object id=(bodyRaw 'carId')))}}
{
  "carId": "{{id}}",
  "startDate": "{{body 'startDate'}}",
  "endDate": "{{body 'endDate'}}",
  "days": {{body 'days'}},
  "dailyRate": {{dailyPrice}},
  "total": {{multiply dailyPrice (bodyRaw 'days')}}
}
  {{else}}
    {{status 404}}
{
  "code": "CAR_NOT_FOUND",
  "message": "Veículo não encontrado"
}
  {{/with}}
{{else}}
  {{status 400}}
{
  "code": "INVALID_PERIOD",
  "message": "Quantidade de dias inválida"
}
{{/if}}
